package fr.formation.hexagonal.adapter.in.web;
import fr.formation.hexagonal.application.port.in.*; import fr.formation.hexagonal.application.port.out.ReservationPort; import fr.formation.hexagonal.application.service.ResourceNotFound; import fr.formation.hexagonal.domain.Reservation; import java.time.LocalDateTime; import java.util.UUID; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/reservations") class ReservationWebAdapter { private final CreateReservationUseCase create; private final CancelReservationUseCase cancel; private final ReservationPort reservations; ReservationWebAdapter(CreateReservationUseCase create,CancelReservationUseCase cancel,ReservationPort reservations){this.create=create;this.cancel=cancel;this.reservations=reservations;} @PostMapping @ResponseStatus(HttpStatus.CREATED) Reservation post(@RequestBody Request r){return create.create(new CreateReservationUseCase.Command(r.roomId(),r.organizerEmail(),r.participants(),r.startsAt(),r.endsAt()));} @GetMapping("/{id}") Reservation get(@PathVariable UUID id){return reservations.find(id).orElseThrow(()->new ResourceNotFound("Reservation not found"));} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){cancel.cancel(id);} record Request(UUID roomId,String organizerEmail,int participants,LocalDateTime startsAt,LocalDateTime endsAt){} }
